import json
import math

# Antiderivative of ln(1+t)/t^2 on t>0 (t = x-2), verified by differentiation:
# d/dt[-ln(1+t)/t + ln(t/(1+t))] = ln(1+t)/t^2
def F(t):
    return -math.log1p(t) / t + math.log(t / (1.0 + t))

def g(t):
    return math.log1p(t) / (t * t)

def f(x):
    return math.log(x - 1.0) / ((x - 2.0) ** 2)

def simpson(h, a, b, n=20000):
    step = (b - a) / n
    s = h(a) + h(b)
    for i in range(1, n):
        s += (4 if i % 2 else 2) * h(a + i * step)
    return s * step / 3.0

eps0 = 0.5
closed_check = simpson(g, 0.1, eps0) - (F(eps0) - F(0.1))
closed_ok = abs(closed_check) < 1e-6

# First term: int_{2}^{2+eps} = int_0^eps g(t) dt, which diverges as lower limit -> 0.
first_growth = []
for d in [1e-2, 1e-4, 1e-6, 1e-8]:
    part = F(eps0) - F(d)          # int_d^{eps0} g(t) dt
    first_growth.append({
        "lower": d,
        "partial": round(part, 6),
        "partial_plus_ln_d": round(part + math.log(d), 6),  # stays bounded => ~ -ln(d)
    })

# Second term: int_{3-eps}^{3} f(x) dx -> 0 as eps -> 0 (integrand continuous at 3)
second_terms = []
for e in [1e-1, 1e-2, 1e-3]:
    second_terms.append({"eps": e, "value": round(simpson(f, 3.0 - e, 3.0, 2000), 8)})

growing = all(first_growth[i + 1]["partial"] > first_growth[i]["partial"]
              for i in range(len(first_growth) - 1))
second_to_zero = abs(second_terms[-1]["value"]) < abs(second_terms[0]["value"])

result = {
    "final_answer": "+infinity (the expression diverges; no finite limit exists)",
    "evidence": {
        "closed_form_check_passed": closed_ok,
        "first_integral_partials": first_growth,
        "first_integral_monotone_increasing_as_lower_limit_to_0": growing,
        "second_integral_values": second_terms,
        "second_integral_tends_to_0": second_to_zero,
        "reason": "integrand ~ 1/(x-2) near x=2 with positive sign, so the [2,2+eps] piece is divergent for every eps>0"
    }
}

