# Verify the submitted completion for the bracket sequence by stack simulation.
# Input: "{ [ [ ] [ ]"   Submitted: "] ] }"

PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())


def is_balanced_sequence(s):
    """Return True if every bracket in s is properly matched and nested."""
    stack = []
    for ch in s:
        if ch in OPENERS:
            stack.append(ch)
        elif ch in PAIRS:
            if not stack or stack[-1] != PAIRS[ch]:
                return False
            stack.pop()
    return not stack


def open_stack(s):
    """Return the unmatched openers left after scanning s, in order."""
    stack = []
    for ch in s:
        if ch in OPENERS:
            stack.append(ch)
        elif ch in PAIRS:
            if stack and stack[-1] == PAIRS[ch]:
                stack.pop()
            else:
                return None  # mismatched closer; prefix is not completable
    return stack


def completion_for(s):
    """Compute the exact closers needed to balance s (innermost first)."""
    stack = open_stack(s)
    if stack is None:
        return None
    closers = {'(': ')', '[': ']', '{': '}'}
    return ''.join(closers[c] for c in reversed(stack))


INPUT = "{ [ [ ] [ ]"
SUBMITTED = "] ] }"

required = completion_for(INPUT)
print("Input:", INPUT)
print("Required completion (computed):", required)
print("Submitted completion:", SUBMITTED)

