from fractions import Fraction as F

# f(x) = x^3 + x^2 - 2x - 1, coefficients stored low -> high
f = [F(-1), F(-2), F(1), F(1)]

def trim(p):
    p = list(p)
    while len(p) > 1 and p[-1] == 0:
        p.pop()
    return p

def ev(p, x):
    r = F(0)
    for c in reversed(p):
        r = r * x + c
    return r

def deriv(p):
    d = [i * p[i] for i in range(1, len(p))]
    return trim(d) if d else [F(0)]

def poly_rem(a, b):
    a = trim(a)
    db = len(b) - 1
    while len(a) - 1 >= db and not (len(a) == 1 and a[0] == 0):
        shift = len(a) - 1 - db
        coef = a[-1] / b[-1]
        for i in range(db + 1):
            a[shift + i] -= coef * b[i]
        a = trim(a)
    return a

def sturm_chain(p):
    chain = [trim(p), deriv(p)]
    while len(chain[-1]) > 1:
        r = poly_rem(chain[-2], chain[-1])
        if r == [F(0)]:
            break
        chain.append([-c for c in r])
    return chain

def sign_changes(vals):
    s = [v for v in vals if v != 0]
    return sum(1 for i in range(len(s) - 1) if (s[i] > 0) != (s[i + 1] > 0))

CHAIN = sturm_chain(f)

def count_open(a, b):
    # exact number of distinct real roots in open interval (a, b)
    # endpoints are checked to be non-roots before use
    assert ev(f, a) != 0 and ev(f, b) != 0
    va = sign_changes([ev(p, a) for p in CHAIN])
    vb = sign_changes([ev(p, b) for p in CHAIN])
    return va - vb

def bisect(a, b, n=80):
    fa = ev(f, a)
    for _ in range(n):
        m = (a + b) / 2
        fm = ev(f, m)
        if (fm > 0) == (fa > 0):
            a, fa = m, fm
        else:
            b = m
    return float((a + b) / 2)

# Discriminant of x^3+ax^2+bx+c with a=1,b=-2,c=-1
a_, b_, c_ = 1, -2, -1
disc = 18*a_*b_*c_ - 4*a_**3*c_ + a_**2*b_**2 - 4*b_**3 - 27*c_**2
print("discriminant =", disc, "(positive => three distinct real roots)")

# Cauchy bound: all roots satisfy |x| < 1 + max|coeff| = 3
print("total distinct real roots in (-3,3) =", count_open(F(-3), F(3)))

options = {
    "A": (F(-2), F(-1)),
    "B": (F(-1), F(0)),
    "C": (F(0), F(1)),
    "D": (F(1), F(2)),
}

for k, (a, b) in options.items():
    print(f"option {k} = ({a}, {b}): f(a)={ev(f, a)}, f(b)={ev(f, b)}, "
          f"roots inside = {count_open(a, b)}")

for k, (a, b) in options.items():
    if count_open(a, b) > 0:
        print(f"approx root in option {k}: {bisect(a, b):.10f}")

selected = "A"
zero_opts = [k for k, (a, b) in options.items() if count_open(a, b) == 0]
print("options that cannot contain a root:", zero_opts)

a, b = options[selected]
if selected in zero_opts:
    print("CHECK PASS")
else:
