def sub(p, q):
    return tuple(a - b for a, b in zip(p, q))

def dot(p, q):
    return sum(a * b for a, b in zip(p, q))

def sqnorm(p):
    return dot(p, p)

def cross(p, q):
    return (p[1] * q[2] - p[2] * q[1],
            p[2] * q[0] - p[0] * q[2],
            p[0] * q[1] - p[1] * q[0])

