# Polynomials in x, y as dicts {(i, j): coeff} meaning coeff * x^i * y^j.
def padd(p, q, s=1):
    r = dict(p)
    for k, v in q.items():
        r[k] = r.get(k, Fraction(0)) + s * v
    return {k: v for k, v in r.items() if v != 0}

def pmul(p, q):
    r = {}
    for (a, b), u in p.items():
        for (c, d), v in q.items():
            key = (a + c, b + d)
            r[key] = r.get(key, Fraction(0)) + u * v
    return {k: v for k, v in r.items() if v != 0}

def const(c):
    return {(0, 0): Fraction(c)}

X = {(1, 0): Fraction(1)}
Y = {(0, 1): Fraction(1)}

def lin(a, b, c):
    # a*x + b*y + c
    return padd(padd({(1, 0): Fraction(a)}, {(0, 1): Fraction(b)}), const(c))

