import math

def f(t):
    # f(t) = t + sqrt(t^2 + 1) is strictly increasing and positive on all reals
    return t + math.sqrt(t * t + 1.0)

samples = [k / 4.0 for k in range(-40, 41)]  # exact binary fractions in [-10, 10]

# Identity check: f(x) * f(-x) == 1 for every sample
