# Monotonicity check: f strictly increasing on the samples, so f(y) = 1/f(x) has at most one solution
mono = all(f(a) < f(b) for a, b in zip(samples, samples[1:]))

def solve_y(x):
    # Bisection for y with f(y) = 1/f(x), using the strict monotonicity of f
    target = 1.0 / f(x)
    lo, hi = -1e3, 1e3
    for _ in range(200):
        mid = (lo + hi) / 2.0
        if f(mid) < target:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2.0

